{
  "concepts": [],
  "definitions": [
    {
      "term": {
        "text": "Math class",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "The Math class is defined in the java.lang package, is always available without explicit import, and provides static methods for performing mathematical operations.",
        "refs": ["Q0001"]
      },
      "context": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "round method with float",
        "refs": ["Q0001"]
      },
      "example_type": null,
      "example_text": {
        "text": "Passing 1.1 as a float to Math.round returns 1 (stored in an int).",
        "refs": ["Q0002"]
      }
    },
    {
      "exemplifies": {
        "text": "ceil method",
        "refs": ["Q0002"]
      },
      "example_type": null,
      "example_text": {
        "text": "Math.ceil(1.1) returns 2 (a double), which must be cast to int to store in an integer variable.",
        "refs": ["Q0002"]
      }
    },
    {
      "exemplifies": {
        "text": "floor method",
        "refs": ["Q0003"]
      },
      "example_type": null,
      "example_text": {
        "text": "Math.floor(1.1) returns 1 (the largest integer less than or equal to the number).",
        "refs": ["Q0003"]
      }
    },
    {
      "exemplifies": {
        "text": "max method with integers",
        "refs": ["Q0003"]
      },
      "example_type": null,
      "example_text": {
        "text": "Math.max(1, 2) returns 2, the greater of the two integer arguments.",
        "refs": ["Q0003"]
      }
    },
    {
      "exemplifies": {
        "text": "min method with integers",
        "refs": ["Q0004"]
      },
      "example_type": null,
      "example_text": {
        "text": "Math.min(1, 2) returns 1, the smaller of the two integer arguments.",
        "refs": ["Q0004"]
      }
    },
    {
      "exemplifies": {
        "text": "random method",
        "refs": ["Q0004"]
      },
      "example_type": null,
      "example_text": {
        "text": "Math.random() returns a double between 0.0 (inclusive) and 1.0 (exclusive); multiplying by 100 yields a random number between 0 and 100.",
        "refs": ["Q0004", "Q0005"]
      }
    }
  ],
  "explanations": [],
  "facts": [
    {
      "fact_text": {
        "text": "Math.round is overloaded: one version takes a float and returns an int; another version takes a double and returns a long.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.ceil returns the smallest integer greater than or equal to the argument (as a double).",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.floor returns the largest integer less than or equal to the argument (as a double).",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.max returns the greater of two values and is overloaded for int, long, float, and double.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.min returns the smaller of two values and is overloaded for int, long, float, and double.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.random returns a double value uniformly distributed between 0.0 (inclusive) and 1.0 (exclusive).",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [],
  "relationships": [],
  "excluded": []
}
